:root {
  --yellow: #f9c22e;
  --yellow-light: #fef3c7;
  --yellow-dark: #d97706;
  --green: #4ade80;
  --green-dark: #16a34a;
  --text-dark: #1c1917;
  --text-mid: #57534e;
  --white: #ffffff;
  --border: #fde68a;
}

.lemonade-card {
  background-color: var(--white);
  border: 3px solid var(--yellow);
  border-radius: 14px;
  padding: 12px 16px;
  max-width: 340px;
  margin: 10px auto;
}

.card-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  background-color: var(--yellow-light);
  border-radius: 8px;
  padding: 8px 12px;
  margin-bottom: 10px;
}

.icon {
  font-size: 28px;
  line-height: 1;
}

.header-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.card-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--yellow-dark);
  margin: 0;
  line-height: 1.2;
}

.card-tagline {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-mid);
  margin: 0;
  letter-spacing: 0.06em;
}

.menu-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.menu-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 10px;
  border: 1.5px solid var(--border);
  border-radius: 7px;
  background-color: var(--yellow-light);
}

.item-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dark);
}

.item-price {
  font-size: 13px;
  font-weight: 700;
  color: var(--yellow-dark);
}

.card-footer {
  margin-top: 10px;
  display: flex;
  justify-content: center;
}

.badge {
  background-color: var(--green);
  color: var(--green-dark);
  font-size: 11px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 999px;
}
